const productsData = [/* نفس بياناتك بدون تغيير */];

/* =========================
   CREATE PRODUCT CARD
========================= */
function createProductCard(e) {
    const t = document.createElement("div");
    t.className = "product-card";
    t.dataset.category = e.category;

    if (e.status === "soon") {
        t.classList.add("soon");
    } else {
        t.addEventListener("click", () => {
            window.location.href = `product.html?id=${e.id}`;
        });
    }

    let n = "";

    if (e.oldPrice) {
        n = `
            <span class="old-price">${e.oldPrice} ر.س</span>
            <span class="new-price">${e.price} ر.س</span>
        `;
    } else if (e.status === "out_of_stock") {
        n = "نفذت الكمية";
    } else if (e.status === "soon") {
        n = "قريبًا";
    } else {
        n = e.price + " ر.س";
    }

    t.innerHTML = `
        <div class="product-image-box">
            <img src="${e.image}">
            ${e.status === "soon" ? '<span class="soon-badge">قريبًا</span>' : ""}
            ${e.oldPrice ? '<span class="discount-badge">خصم</span>' : ""}
        </div>

        <h3>${e.title}</h3>
        <p class="price">${n}</p>

        ${e.status === "available" ? `
            <button class="add-to-cart"
                data-id="${e.id}"
                data-title="${e.title}"
                data-price="${e.price}"
                data-image="${e.image}">
                إضافة للسلة
            </button>

            <button class="buy-now-btn"
                onclick="event.stopPropagation(); buyNow(${e.id});">
                شراء الآن
            </button>
        ` : `
            <button class="buy-now-btn disabled" disabled>
                شراء الآن
            </button>
        `}
    `;

    return t;
}

/* =========================
   BUY NOW
========================= */
function buyNow(id) {
    const user = JSON.parse(localStorage.getItem("loggedUser") || "null");
    if (!user || !user.email) {
        window.location.href = "account.html";
        return;
    }

    const product = productsData.find(p => p.id === id);
    if (product?.paypal) {
        window.location.href = product.paypal;
    }
}

/* =========================
   CART SAFE HANDLING
========================= */
function getCart() {
    try {
        return JSON.parse(localStorage.getItem("cart")) || [];
    } catch {
        return [];
    }
}

function saveCart(cart) {
    localStorage.setItem("cart", JSON.stringify(cart));
}

/* =========================
   ADD TO CART (FIXED)
========================= */
function activateAddToCartButtons() {
    document.querySelectorAll(".add-to-cart").forEach(btn => {
        btn.addEventListener("click", (e) => {
            e.stopPropagation();

            const id = Number(btn.dataset.id);
            const title = btn.dataset.title;
            const price = Number(btn.dataset.price);
            const image = btn.dataset.image;

            // ❌ منع أي سعر غير صالح
            if (!isFinite(price)) return;

            let cart = getCart();

            const existing = cart.find(i => i.id === id);

            if (existing) {
                existing.qty += 1;
            } else {
                cart.push({
                    id,
                    title,
                    price,
                    image,
                    qty: 1
                });
            }

            saveCart(cart);

            showNiceAlert("تمت إضافة المنتج للسلة");
            updateCartCount();
        });
    });
}

/* =========================
   ALERT
========================= */
function showNiceAlert(msg) {
    const el = document.getElementById("niceAlert");
    if (!el) return;

    el.textContent = msg;
    el.classList.add("show");

    setTimeout(() => {
        el.classList.remove("show");
    }, 2000);
}

/* =========================
   RENDER PRODUCTS
========================= */
const productsGrid = document.getElementById("productsGrid");

if (productsGrid) {
    productsGrid.innerHTML = "";

    if (!window.location.search.includes("cat=")) {
        productsData.forEach(p => {
            productsGrid.appendChild(createProductCard(p));
        });
    }

    activateAddToCartButtons();
}

/* =========================
   CART COUNT
========================= */
function updateCartCount() {
    const cart = getCart();

    const count = cart.reduce((s, i) => {
        const qty = Number(i.qty);
        return s + (isFinite(qty) ? qty : 0);
    }, 0);

    const el = document.querySelector(".cart-count") || document.getElementById("cartCount");
    if (el) el.textContent = count;
}

/* =========================
   CART ICON CLICK
========================= */
const cartIcon = document.querySelector(".cart-icon");

if (cartIcon) {
    cartIcon.addEventListener("click", () => {
        const user = JSON.parse(localStorage.getItem("loggedUser") || "null");
        window.location.href = (user && user.email) ? "checkout.html" : "account.html";
    });
}

updateCartCount();

/* =========================
   SEARCH (SAFE)
========================= */
const searchIcon = document.querySelector(".search-icon");
const headerEl = document.querySelector("header");
const searchBox = document.querySelector(".search-box");
const searchInput = document.getElementById("searchInput");

function filterProducts(v) {
    if (!productsGrid) return;

    const cards = productsGrid.querySelectorAll(".product-card");
    const q = v.trim().toLowerCase();

    cards.forEach(card => {
        const title = card.querySelector("h3")?.textContent.toLowerCase() || "";
        card.style.display = title.includes(q) ? "" : "none";
    });
}

/* =========================
   PROFILE DROPDOWN (FIXED)
========================= */
const profileIcon = document.getElementById("profileIcon");
const profileDropdown = document.getElementById("profileDropdown");

if (profileIcon && profileDropdown) {
    profileIcon.addEventListener("click", () => {
        const user = JSON.parse(localStorage.getItem("loggedUser") || "null");

        if (!user) {
            window.location.href = "account.html";
            return;
        }

        profileDropdown.classList.toggle("show");
    });

    document.addEventListener("click", (e) => {
        if (!profileIcon.contains(e.target) && !profileDropdown.contains(e.target)) {
            profileDropdown.classList.remove("show");
        }
    });
}

/* =========================
   SIDE MENU (SAFE)
========================= */
const sideMenu = document.getElementById("sideMenu");
const sideMenuBtn = document.getElementById("sideMenuBtn");

if (sideMenu && sideMenuBtn) {
    sideMenuBtn.addEventListener("click", () => {
        sideMenu.classList.toggle("open");
        sideMenuBtn.classList.toggle("hidden");
    });

    document.addEventListener("click", (e) => {
        if (!sideMenu.contains(e.target) && !sideMenuBtn.contains(e.target)) {
            sideMenu.classList.remove("open");
            sideMenuBtn.classList.remove("hidden");
        }
    });
}

/* =========================
   FILTERS
========================= */
const filterCategory = document.getElementById("filterCategory");
const filterPrice = document.getElementById("filterPrice");
const filterStatus = document.getElementById("filterStatus");

function applyFilters() {
    if (!productsGrid) return;

    let list = [...productsData];

    if (filterCategory && filterCategory.value !== "all") {
        list = list.filter(p => p.category === filterCategory.value);
    }

    if (filterPrice && filterPrice.value !== "all") {
        if (filterPrice.value === "low") list = list.filter(p => Number(p.price) < 20);
        if (filterPrice.value === "mid") list = list.filter(p => Number(p.price) >= 20 && Number(p.price) <= 50);
        if (filterPrice.value === "high") list = list.filter(p => Number(p.price) > 50);
    }

    if (filterStatus && filterStatus.value !== "all") {
        list = list.filter(p => p.status === filterStatus.value);
    }

    productsGrid.innerHTML = "";
    list.forEach(p => productsGrid.appendChild(createProductCard(p)));

    activateAddToCartButtons();
}

filterCategory?.addEventListener("change", applyFilters);
filterPrice?.addEventListener("change", applyFilters);
filterStatus?.addEventListener("change", applyFilters);

/* =========================
   CATEGORY FROM URL
========================= */
const urlParams = new URLSearchParams(window.location.search);
const catParam = urlParams.get("cat");

if (catParam && filterCategory) {
    filterCategory.value = catParam;
    applyFilters();
}